from rdkit.Chem import rdFMCS

def correspondence(a,b,timeout=8):
 ma=Chem.RemoveHs(Chem.MolFromSmiles(a['mapped_smiles']));mb=Chem.RemoveHs(Chem.MolFromSmiles(b['mapped_smiles']))
 result=rdFMCS.FindMCS([ma,mb],timeout=timeout,ringMatchesRingOnly=True,atomCompare=rdFMCS.AtomCompare.CompareElements,bondCompare=rdFMCS.BondCompare.CompareAny)
 q=Chem.MolFromSmarts(result.smartsString);aa=ma.GetSubstructMatch(q);bb=mb.GetSubstructMatch(q)
 return {'from':a['id'],'to':b['id'],'atom_map_pairs':[[ma.GetAtomWithIdx(i).GetAtomMapNum(),mb.GetAtomWithIdx(j).GetAtomMapNum()] for i,j in zip(aa,bb)],'meaning':'Deterministic common heavy-atom correspondence; symmetry-equivalent alternatives are allowed if explicitly mapped. Unmatched atoms are the intervention. Match uses element/ring topology, not a claim of unchanged bond orders.','search_timed_out':result.canceled}

